+    const rejectionOf = (call: Promise<unknown>): Promise<unknown> =>
+      call.then(
+        () => 'resolved without throwing',
+        (thrown: unknown) => thrown
+      );
+
+    function createRejectingProvider(reason: unknown): AIProvider {
+      return {
+        // eslint-disable-next-line require-yield
+        async *sendMessage(): AsyncGenerator<MessageChunk> {
+          throw reason;
+        },
+        async generateStructured<T>(): Promise<T> {
+          return {} as T;
+        },
+      };
+    }
+
+    it('wraps a non-Error rejection in an Error whose cause is the original and still rejects the caller with the original', async () => {
+      const cases: Array<{name: string; value: unknown}> = [
+        {name: 'string', value: 'string boom'},
+        {name: 'plain object', value: {code: 503, detail: 'upstream down'}},
+        {name: 'undefined', value: undefined},
+      ];
+
+      for (const {value} of cases) {
+        let onErrorCallCount = 0;
+        let passedError: unknown;
+        const hooks: OrchestratorHooks = {
+          onError: async (_session, error) => {
+            onErrorCallCount++;
+            passedError = error;
+          },
+        };
+
+        const orchestrator = createChatOrchestrator(createRejectingProvider(value), promptBuilder, undefined, {
+          hooks,
+        });
+        const rejection = await rejectionOf(orchestrator.processMessage(createSession('hello')));
+
+        expect({
+          onErrorCallCount,
+          isError: passedError instanceof Error,
+          causeIsOriginal: passedError instanceof Error && (passedError as Error & {cause?: unknown}).cause === value,
+          callerReceivedOriginal: rejection === value,
+        }).toEqual({
+          onErrorCallCount: 1,
+          isError: true,
+          causeIsOriginal: true,
+          callerReceivedOriginal: true,
+        });
+      }
